{
  "name": "opencode-better-worktrees",
  "version": "0.2.0",
  "description": "OpenCode V2 plugin that lets the agent create, list, inspect, switch to and safely remove Git worktrees through OpenCode's native Worktree API",
  "type": "module",
  "license": "MIT",
  "author": "igorovh",
  "homepage": "https://github.com/igorovh/opencode-better-worktrees#readme",
  "bugs": {
    "url": "https://github.com/igorovh/opencode-better-worktrees/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/igorovh/opencode-better-worktrees.git"
  },
  "keywords": ["opencode", "opencode-plugin", "git", "git-worktree", "worktree", "ai-agent"],
  "files": ["index.ts", "src", "README.md", "LICENSE"],
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.5"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.3.0",
    "@types/bun": "1.4.4",
    "typescript": "7.0.2"
  }
}
